import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: true }
});

// Session store - in-memory for simplicity
const sessions = new Map();

// Middleware: extract session
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (token && sessions.has(token)) {
    req.user = sessions.get(token);
  }
  next();
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  const result = await pool.query(
    'SELECT id, username, role FROM users WHERE username = $1 AND password_hash = $2',
    [username, crypto.createHash('sha256').update(password).digest('hex')]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid credentials' });
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, result.rows[0]);
  res.json({ token, user: result.rows[0] });
});

// Template rendering - supports user-defined report templates
app.post('/api/reports/render', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });

  const { templateId, parameters } = req.body;

  // Fetch template from database
  const tmplResult = await pool.query(
    'SELECT body, owner_id, shared FROM report_templates WHERE id = $1',
    [templateId]
  );

  if (tmplResult.rows.length === 0) return res.status(404).json({ error: 'Template not found' });

  const template = tmplResult.rows[0];

  // Access control check
  if (template.owner_id !== req.user.id && !template.shared) {
    return res.status(403).json({ error: 'Access denied' });
  }

  // Render template with parameters
  // Template syntax: {{param_name}} for simple substitution
  // Advanced: {{= expression }} for computed fields
  let rendered = template.body;

  // Simple substitution
  for (const [key, value] of Object.entries(parameters || {})) {
    rendered = rendered.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), String(value));
  }

  // Computed fields - evaluate expressions in template
  const exprRegex = /\{\{=\s*(.+?)\s*\}\}/g;
  let match;
  while ((match = exprRegex.exec(rendered)) !== null) {
    try {
      // Build context with parameters and helper functions
      const context = {
        params: parameters || {},
        now: () => new Date().toISOString(),
        upper: (s) => String(s).toUpperCase(),
        lower: (s) => String(s).toLowerCase(),
        formatDate: (d) => new Date(d).toLocaleDateString(),
      };
      const fn = new Function(...Object.keys(context), `return (${match[1]});`);
      const result = fn(...Object.values(context));
      rendered = rendered.replace(match[0], String(result));
    } catch (e) {
      rendered = rendered.replace(match[0], `[ERROR: ${e.message}]`);
    }
  }

  res.json({ rendered, templateId });
});

// Template CRUD
app.post('/api/templates', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });
  const { name, body, shared } = req.body;
  const result = await pool.query(
    'INSERT INTO report_templates (name, body, owner_id, shared) VALUES ($1, $2, $3, $4) RETURNING id',
    [name, body, req.user.id, shared || false]
  );
  res.json({ id: result.rows[0].id });
});

app.get('/api/templates', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });
  const result = await pool.query(
    'SELECT id, name, shared FROM report_templates WHERE owner_id = $1 OR shared = true',
    [req.user.id]
  );
  res.json(result.rows);
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000, () => console.log('Report service running on :3000'));
